1. **Parsing**: Split the input string into tokens.
2. **Evaluation**: Use a stack to handle nested expressions and apply the operations in the correct order.
3. **Error Handling**: Ensure the expression is well-formed and handle any malformed inputs.

Here's the implementation:

```python
def evaluate(expr: str) -> float:
    def apply_operator(operand1, operator, operand2):
        if operator == '+':
            return round(float(operand1) + float(operand2), 4)
        elif operator == '-':
            return round(float(operand1) - float(operand2), 4)
        elif operator == '*':
            return round(float(operand1) * float(operand2), 4)
        elif operator == '/':
            return round(float(operand1) / float(operand2), 4)
        elif operator == '**':
            return round((float(operand1) ** float(operand2), 4))
        else:
            return 0

    def apply_unary(operand, operator):
        if operator == '-':
            return -1 * float(operand)
        else:
            return 0

    stack = []
    result = 0
    sign = '+'
    i = 0
    while i < len(expr):
        if expr[i] in '+-*/%':
            sign = expr[i]
            i += 1
        elif ord(expr[i:]).isdigit() or (i + 1 < len(expr) and expr[i+1] in '.'):
            num = 0
            while i < len(expr) and (ord(expr[i]).isdigit() or expr[i] in '.') and i < len(expr) - 1:
                if expr[i] == '.':
                    num = (int(num or '0') * 10 + int(expr[i+1])
                else:
                    num = (int(num or '0') * 10 + ord(expr[i+1]) - ord('0'))
                i += 2
            result = apply_unary(sign, result)
        else:
            if not stack:
                return 0
            top = stack.pop()
            if sign in '+':
                result = apply_unary('+', top, result)
            else:
                result = apply_unary('-', top, result)
    return round(result, 4)

# Example usage:
