To solve this problem, we can use a trie data structure to efficiently store and search for words. We'll use a class `WildcardTrie` that manages the trie and provides methods to add words, remove words, and search for patterns. We'll use a set to keep track of the words in the trie.

```python
class WildcardTrie:
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.is_end_of_word = False

    def __init__(self):
        self.root = self.TrieNode()
        self.words = set()

    def add_word(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True
        self.words.add(word)

    def remove_word(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return  # Not found
            }
        return True

    def search(self, pattern):
        self.words = set()
        self._search_helper(pattern, 0, '')
        return list(self.words)

    def _search_helper(self, pattern, index, current_word):
        if index == len(pattern):
            self.words.add(current_word)
            return

        char = pattern[index]
        if char == '.':
            for child in self.root.children.values():
                self._search_helper(pattern, index + 1, current_word + char, node)
        else:
            if char in self.root.children:
                self._search_helper(pattern, index + 1, current_word + char)

    def search(self, pattern):
        return self._search_helper(pattern, 0, '')
