To solve this problem, we need to implement two functions: `to_base` and `from_base`. The `to_base` function will convert an integer to a string representation in a given base, while the `from_base` function will parse a number from a string representation in a specific base. We'll use a dictionary to map the alphabet to its corresponding index for easy lookups.

```python
# Helper function to convert an integer to a string in a given base
def int_to_base(n, base, alphabet):
    if n == 0:
            return '0'
    digits = []
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base
    return ''.join(reversed(digits))

# Helper function to convert a number from a string representation in a given base
def base_to_int(s, base, alphabet):
    num = 0
    for i, c in enumerate(reversed(s)):
        if c not in alphabet:
            return None  ####################
    return int(''.join(s) * (base ** (len(s) - 1)), base)

# Main function to convert an integer to a number in a given base
def to_base(n, alphabet):
    if n < 0:
        sign = -1
        n = -n
    else:
        sign = 0

    if n == 0:
        return '0'

    result = ''
    while n > 0:
        result = alphabet[n % len(alphabet)] + result
        n //= len(alphabet)

    return '0' if not result else result

# Helper function to convert a number from its base representation in a string
def from_base(s, alphabet):
    if not s:
        return ''

    result = 0
    for i, c in enumerate(reversed(s)):
        if c not in alphabet:
            return None  # Invalid character found

    for i, c in enumerate(reversed(s)):
        if c not in alphabet:
            result += (alphabet.index(c)) * (len(s) ** i)

    return result

# Example usage:
alphabet = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
print(to_base(10, 2))  # Output: '1010'
print(from_base('1101', 2).decode())  # Output: 13
```

