To solve this problem, we need to parse a CSV string into rows. We'll use a stack to keep track of the current row and the state of the line being parsed. We'll iterate through each character in the input string, updating the current row and state as we go. If a new line is encountered, we'll process the current row and reset the state for the next line.

```python
def parse_csv_stream(chunks):
    stack = [{}]
    for chunk in chunks:
        line = ''.join(chunk)
        if line.startswith('"') or line.startswith("'"):
            # Handle quoted strings
            if line.startswith('"') or line.startswith("'"):
                start = line.find('"')
                end = line.rfind('"', start+1, len(line) - 2)
                if end == -1:
                    raise ValueError("Unterminated string")
                yield [''.join(line[start+1:end])]
            else:
                start = line.find("'")
                end = line.rfind("'", start+1, len(line) - 2)
                if end == -1:
                    raise ValueError("Unterminated string")
        else:
            for c in line:
                if c in [',', '\n']:
                    if stack[-1].get('row') == '' and stack[-1]['col'] + 1 < len(line):
                        stack[-1]['row'] += line
                    else:
                        if stack[-1].get('row'):
                            yield stack.pop()
                        stack.append({'col': 0, 'row': '', 'start_col': -1, 'end_col': -1})
                    stack[-1]['col'] = line.index(c)
            else:
                if c in [',', '\n']:
                    stack[-1]['col'] = line.index(c, stack[-1]['col'] + 1)
    else:
        if stack and stack[-1]['row']:
            yield stack.pop()

# Example usage
chunks = [["a", "b", 'c"d" efg', 'hijkl', '"k"lmn', 'p"qrst"uv', 'x"y"z']]
for row in parse_csv_stream(chits):
    print(row)
