Here's the implementation:

```javascript
// Helper function to create a promise that resolves after a given time
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// Helper function to process tasks asynchronously
const processTasks = (tasks) => {
  const results = new Set();
  let currentTask = 0;

  return async (value, ...args) => {
    if (currentTask < tasks.length) {
      const task = tasks[currentTask++];
      try {
        return await task(value, ...args);
      } catch (err) {
        console.error(`Task ${currentTask - 1} failed: ${err.message}`);
      }
    } else {
      return new Promise(resolve => setTimeout(() => resolve(), 0));
    }
  };
};

module.exports = pLimit;

