To solve the problem of creating a lazy, infinite iterator that processes elements from multiple input iterators and fills in missing values with a specified fill value. The approach will be to use a priority queue to keep track of the next item to process, with the key being the position in the input iterable. We'll use a set to keep track of which inputs have been processed.

Here's the implementation:

```javascript
// Helper function to create a priority queue
const pq = (arr) => {
  return new PriorityQueue(...arr);
};

// Helper function to create a priority queue
class PriorityQueue {
  constructor(iter) {
    this.heap = [];
    if (iter) this.heap = iter;
  }

  push(val, priority) {
    this.heap.push({ value: val, priority });
    this.bubbleUp();
  }

  pop() {
    return this.heap.shift().value;
  }

  get length() {
    return this.heap.length;
  }

  bubbleUp() {
    let current = this.heap.length - 1;
    while (current > 0) {
      const parent = Math.floor((current - 1) / 2);
      if (this.heap[current].priority < this.heap[parent].priority) {
        [this.heap[current], this.flow(0, current)] = [
          this.flow(current, parent),
          this.heap[parent],
        ][0];
        current = parent;
      } else {
        break;
      }
    }
  }

  bubbleDown() {
    let current = 0;
    while (true) {
      const leftChild = 2 * current + 1;
      let rightChild = leftChild + 1;
      if (leftChild < this.heap.length) {
        const min = leftChild;
        if (rightChild < this.heap.length && this.heap[rightChild].priority < this.heap[min].priority) {
          min = rightChild;
        }
        if (this.heap[current] < this.heap[min]) {
          [this.heap[current], this.flow(min, current), this.heap[min]] = [
            this.flow(min, current),
            this.heap[min],
          ][0];
          current = min;
        } else {
          break;
        }
      } else if (this.heap[current] < this.flow(current, min), this.heap[min]]) {
          [this.heap[current], this.heap[min]] = [this.flow(min, current), this.heap[min]];
          current = min;
        } else {
          break;
        }
      }
    }
  }

  flow(from, to) {
    return (v, i, arr) => (i < from ? v : this.heap[arr.indexOf(this.heap[i], from) + 1]);
  }

  get length() {
    return this.heap.length;
  }
