export type Handler<T> = (value: T) => unknown;
export type Matches<T, R> = [T, ...(R extends any ? [T] : [])];

export function match<TReturn, TValue, TError = unknown>(value: any, handlers: Handler<T>[]): Matches<TReturn, TValue | TError> {
